export function getTechSlug(name: string): string {
  if (!name) return 'technology';
  const customMap: Record<string, string> = {
    'NodeJS': 'nodejs',
    'Node.js': 'nodejs',
    'Node.js (v22)': 'nodejs',
    '.NET (C#)': 'dotnet',
    '.NET': 'dotnet',
    '.NET MAUI & Ionic': 'dotnet-maui',
    'PHP': 'php',
    'Python': 'python',
    'Laravel': 'laravel',
    'Django': 'django',
    'Ruby on Rails': 'ruby-on-rails',
    'CodeIgniter': 'codeigniter',
    'CakePHP': 'cakephp',
    'Go (Golang)': 'golang',
    'Java Spring Boot': 'java-spring-boot',
    'NestJS & Express': 'nestjs-express',
    'GraphQL & gRPC': 'graphql-grpc',
    'React 19': 'react',
    'Next.js 16': 'nextjs',
    'TypeScript 5': 'typescript',
    'Vue 3 / Nuxt': 'vuejs-nuxt',
    'Angular': 'angular',
    'Tailwind CSS v4': 'tailwind-css',
    'Three.js (3D & WebGL)': 'threejs',
    'Framer Motion': 'framer-motion',
    'Svelte / SvelteKit': 'svelte',
    'React Native': 'react-native',
    'Flutter': 'flutter',
    'Swift (iOS)': 'swift',
    'Kotlin (Android)': 'kotlin',
    'Expo': 'expo',
    'MariaDB 3.5+': 'mariadb',
    'PostgreSQL': 'postgresql',
    'Redis': 'redis',
    'Pinecone Vector DB': 'pinecone',
    'Microsoft SQL Server': 'mssql',
    'MongoDB': 'mongodb',
    'Snowflake & BigQuery': 'snowflake-bigquery',
    'Firebase & Supabase': 'firebase-supabase',
    'Amazon Web Services (AWS)': 'aws',
    'Google Cloud Platform (GCP)': 'gcp',
    'Microsoft Azure': 'azure',
    'Docker': 'docker',
    'Kubernetes (K8s)': 'kubernetes',
    'Terraform': 'terraform',
    'OpenAI & GPT-4o': 'openai-gpt4',
    'Claude & Anthropic': 'claude-anthropic',
    'PyTorch': 'pytorch',
    'TensorFlow & TensorRT': 'tensorflow',
    'LangChain & LlamaIndex': 'langchain',
    'Hugging Face Transformers': 'huggingface',
    'Computer Vision & OpenCV': 'computer-vision',
    'NLP & SpaCy': 'nlp-spacy',
    'vLLM & Ollama': 'vllm-ollama',
    'CrewAI & AutoGPT': 'crewai-agents',
    'MLflow & Kubeflow': 'mlflow-kubeflow',
    'Apache Spark & Big Data': 'apache-spark',
    'Laravel Custom Commerce': 'laravel-commerce',
    'Shopify & Shopify Plus': 'shopify',
    'Magento 2 (Adobe Commerce)': 'magento',
    'WordPress & WooCommerce': 'wordpress',
    'Strapi (Headless CMS)': 'strapi',
    'Payload CMS / Sanity': 'payload-cms',
  };

  if (customMap[name]) return customMap[name];

  return name
    .toLowerCase()
    .replace(/[()&/\\.+]/g, '')
    .trim()
    .replace(/\s+/g, '-');
}

